package com.l4d.infected.client;

import com.l4d.infected.entity.SmokerInfected;
import net.minecraft.client.model.geom.ModelPart;

import static com.l4d.infected.client.Anim.*;
import static com.l4d.infected.entity.SmokerInfected.*;
import static net.minecraft.util.Mth.cos;
import static net.minecraft.util.Mth.sin;

/** model spec: assets/l4dinfected/models/entity/smoker.json (generated by tools/tex_smoker.py) */
public class SmokerModel extends InfectedModel<SmokerInfected> {
    private float sac;

    public SmokerModel(ModelPart root) { super(root, "smoker"); }

    private void r(String n, float x, float y, float z) { ModelPart p = part(n); p.xRot += x; p.yRot += y; p.zRot += z; }

    @Override
    public void setupAnim(SmokerInfected e, float ls, float la, float age, float yaw, float pitch) {
        super.setupAnim(e, ls, la, age, yaw, pitch);
        ModelPart s = part("sac");
        s.xScale = s.zScale = sac; s.yScale = 0.5f + 0.5f * sac;
    }

    /** loping, hunched gait: long slow strides with knees that fold, dangling arms, coat rags flapping. */
    @Override
    protected void locomotion() {
        ModelPart head = part("head");
        head.xRot += head.getInitialPose().xRot;   // base setupAnim overwrote the authored tilt with head pitch
        float s = limbAmt, c = limb * 0.55f, br = sin(age * 0.07f), sw = cos(c);
        r("body", 0.08f * s + 0.03f * br, sw * 0.1f * s, sw * 0.05f * s);
        r("chest", 0.04f * br, 0, 0);
        r("neck", -0.04f * br, 0, 0);
        head.xRot += -0.06f * s + Math.abs(sin(c)) * 0.1f * s;
        head.zRot += 0.06f * sin(age * 0.03f);   // idle head cant
        r("jaw", 0.06f + 0.06f * sin(age * 0.05f), 0, 0);
        r("right_leg", sw * 0.8f * s, 0, 0);
        r("left_leg", -sw * 0.8f * s, 0, 0);
        r("right_shin", Math.max(0, sin(c)) * 1.1f * s, 0, 0);
        r("left_shin", Math.max(0, -sin(c)) * 1.1f * s, 0, 0);
        r("right_arm", -sw * 0.4f * s + 0.03f * br, 0, 0.04f * sin(age * 0.06f));
        r("left_arm", sw * 0.4f * s + 0.03f * br, 0, -0.04f * sin(age * 0.06f + 1));
        r("right_forearm", -0.2f * s, 0, 0);
        r("left_forearm", -0.2f * s, 0, 0);
        r("right_hand", sin(age * 0.4f) * 0.06f, 0, 0);
        r("left_hand", sin(age * 0.37f + 2) * 0.06f, 0, 0);
        r("coat_right", Math.min(0, sw) * 0.7f * s, 0, 0);
        r("coat_left", Math.min(0, -sw) * 0.7f * s, 0, 0);
        r("coat_back", 0.3f * s + 0.05f * sin(age * 0.1f), 0, 0);
        r("tongue_tip", 0.5f * s + 0.12f * sin(age * 0.09f), 0, 0.2f * sin(age * 0.11f));
        sac = 1 + 0.05f * sin(age * 0.12f);
    }

    @Override
    protected void action(int id) {
        float t = ent.actionTime(pt);
        switch (id) {
            case TONGUE -> tongue(t);
            case PULL -> reel(1, t);
            case CHOKE -> { float b = smooth(seg(t, 0, 8)); reel(1 - b, t); choke(b, t); }
            case RETRACT -> reel(1 - smooth(seg(t, 0, 8)), t);
            case RECOIL -> recoil(t);
            default -> {}
        }
    }

    /** coil (rear back, sac swells, arms spread) -> head thrust + maw gapes as the tongue fires -> settle into the reel. */
    private void tongue(float t) {
        float wind = smooth(seg(t, 0, TONGUE_HIT - 3)), strike = out(seg(t, TONGUE_HIT - 3, TONGUE_HIT)), settle = smooth(seg(t, TONGUE_HIT, TONGUE_LEN));
        float k = wind * (1 - strike), st = strike * (1 - settle);
        float shudder = sin(t * 3.1f) * 0.05f * k;
        r("body", -0.15f * k + 0.15f * st, 0, 0);
        r("chest", -0.4f * k + 0.5f * st, shudder, 0);
        r("neck", -0.3f * k + 0.6f * st, 0, 0);
        r("head", -0.5f * k + 0.4f * st, shudder, 0);
        r("jaw", 0.3f * k + 1.0f * st, 0, 0);
        for (int i = -1; i <= 1; i += 2) {
            String side = i < 0 ? "right" : "left";
            r(side + "_arm", 0.4f * k + 0.6f * st, 0, -i * 0.5f * k);
            r(side + "_forearm", -0.4f * k, 0, 0);
            r(side + "_hand", -0.4f * k + 0.3f * st, 0, 0);
        }
        r("right_leg", -0.25f * k - 0.4f * st, 0, 0);
        r("left_leg", -0.25f * k + 0.2f * st, 0, 0);
        r("right_shin", 0.45f * k, 0, 0);
        r("left_shin", 0.45f * k, 0, 0);
        sac += 0.45f * k - 0.3f * st;
        if (t > TONGUE_HIT - 3) part("tongue_tip").visible = false;
        reel(settle, t);
    }

    /** braced stance, head thrust forward, maw open; hand-over-hand reeling and gulping sac. */
    private void reel(float w, float t) {
        if (w <= 0) return;
        float ph = sin(t * 0.5f);
        part("tongue_tip").visible = false;
        r("right_leg", -0.35f * w, 0, 0); r("left_leg", 0.3f * w, 0, 0);
        r("right_shin", 0.2f * w, 0, 0); r("left_shin", 0.1f * w, 0, 0);
        r("body", -0.12f * w, 0, 0);
        r("chest", (-0.15f + 0.06f * ph) * w, 0, 0);
        r("neck", 0.35f * w, 0, 0);
        r("head", 0.25f * w, 0, 0);
        r("jaw", 0.7f * w, 0, 0);
        r("right_arm", (-0.9f + 0.35f * ph) * w, -0.2f * w, 0);
        r("left_arm", (-0.9f - 0.35f * ph) * w, 0.2f * w, 0);
        r("right_forearm", (-0.5f - 0.3f * Math.max(0, ph)) * w, 0, 0);
        r("left_forearm", (-0.5f - 0.3f * Math.max(0, -ph)) * w, 0, 0);
        sac += 0.18f * Math.max(0, ph) * w;
    }

    /** both hands clamp the lifted victim's throat; every grip cycle squeezes (damage frame) with a shudder and head tilt. */
    private void choke(float b, float t) {
        float u = (t % CHOKE_PERIOD) / CHOKE_PERIOD;
        float sq = bump(u, 0.3f, 0.5f, 0.75f), shud = sin(t * 2.7f) * 0.05f * sq;
        part("tongue_tip").visible = false;
        r("right_leg", -0.25f * b, 0, 0.12f * b); r("left_leg", 0.2f * b, 0, -0.12f * b);
        r("right_shin", 0.25f * b, 0, 0); r("left_shin", 0.3f * b, 0, 0);
        r("body", -0.18f * b, 0, 0);
        r("chest", (-0.1f - 0.08f * sq + shud) * b, shud * b, 0);
        r("neck", 0.25f * b, 0, 0);
        r("head", (0.2f + 0.1f * sq) * b, shud * 2 * b, 0.35f * (0.6f + 0.4f * sq) * b);
        r("jaw", (0.5f + 0.4f * sq) * b, 0, 0);
        r("right_arm", (-1.5f - 0.15f * sq) * b, (-0.35f - 0.2f * sq) * b, 0);
        r("left_arm", (-1.5f - 0.15f * sq) * b, (0.35f + 0.2f * sq) * b, 0);
        r("right_forearm", (-0.35f - 0.25f * sq) * b, 0, 0);
        r("left_forearm", (-0.35f - 0.25f * sq) * b, 0, 0);
        r("right_hand", -0.5f * sq * b, 0, 0);
        r("left_hand", -0.5f * sq * b, 0, 0);
        sac += (0.1f + 0.3f * sq) * b;
    }

    /** tongue snapped: head whips back, arms fling up, stumbles a step, sac deflates. */
    private void recoil(float t) {
        float k = bump(t / 14f, 0, 0.15f, 1), shake = sin(t * 2f) * 0.3f * k;
        r("head", -0.8f * k, shake, 0);
        r("neck", -0.4f * k, 0, 0);
        r("jaw", 0.9f * k, 0, 0);
        r("chest", -0.4f * k, 0, 0);
        r("right_arm", -1.2f * k, 0, 0.6f * k);
        r("left_arm", -1.0f * k, 0, -0.6f * k);
        r("right_forearm", -0.6f * k, 0, 0); r("left_forearm", -0.6f * k, 0, 0);
        r("right_leg", 0.4f * k, 0, 0); r("left_leg", -0.2f * k, 0, 0);
        sac -= 0.3f * k;
    }

    /** base claw + an elbow that cocks back then whips the long forearm through, talons curling on impact. */
    @Override
    protected void claw() {
        super.claw();
        float p = ent.actionProgress(pt);
        String side = ent.alt() ? "left" : "right";
        float wind = smooth(seg(p, 0, 0.38f)), strike = in(seg(p, 0.38f, 0.52f)), rec = smooth(seg(p, 0.55f, 1));
        r(side + "_forearm", (-0.9f * wind * (1 - strike) + 0.25f * strike) * (1 - rec), 0, 0);
        r(side + "_hand", (-0.5f * wind + 0.6f * strike) * (1 - rec), 0, 0);
        r("jaw", 0.4f * strike * (1 - rec), 0, 0);
    }
}
